import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    """
    Extracts all URLs from a string-serialized JSON dict using a regex pattern
    and returns a dict with the URLs as keys and their frequency as values.
    """
    # Parse the JSON string into a Python dictionary
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {}

    # Define a URL pattern (matches http/https URLs)
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+[/\w\.-]*'

    # Helper function to recursively find all strings in the JSON structure
    def extract_strings(obj):
        strings = []
        if isinstance(obj, str):
            strings.append(obj)
        elif isinstance(obj, dict):
            for value in obj.values():
                strings.extend(extract_strings(value))
        elif isinstance(obj, list):
            for item in obj:
                strings.extend(extract_strings(item))
        return strings

    # Get all strings from the JSON object
    all_strings = extract_strings(data)

    # Find all URLs in the collected strings
    found_urls = []
    for s in all_strings:
        found_urls.extend(re.findall(url_pattern, s))

    # Count occurrences
    counts = Counter(found_urls)

    # Return the top_n most common URLs as a dict
    return dict(counts.most_common(top_n))

