import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    """
    Validates a JSON file against a schema and retrieves a specific attribute.
    """
    # 1. Check if file exists
    if not os.path.exists(file_path):
        raise ValueError(f"File not found: {file_path}")

    # 2. Load JSON content
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format in file.")

    # 3. Validate required fields
    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")

    # 4. Validate types and specific formats
    properties = INPUT_JSON.get("properties", {})
    for key, value in data.items():
        if key in properties:
            expected_type = properties[key]["type"]
            if not isinstance(value, expected_type):
                raise ValueError(f"Attribute '{key}' must be of type {expected_type.__name__}")

            # Special check for email format
            if key == "email":
                if not re.match(EMAIL_REGEX, value):
                    raise ValueError(f"Invalid email format: {value}")

    # 5. Retrieve specified attribute
    if attribute not in data:
        raise ValueError(f"Requested attribute '{attribute}' not found in JSON.")

    return data[attribute]

