import re
import urllib.request
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    """
    Fetches the public IP address from the provided API_URL.

    Args:
        API_URL (str): The URL of the API to fetch the IP from.

    Returns:
        str: The public IP address.

    Raises:
        Exception: If the API request fails or the IP cannot be parsed.
    """
    try:
        with urllib.request.urlopen(API_URL, timeout=10) as response:
            if response.status != 200:
                raise Exception(f"API request failed with status code: {response.status}")

            data = response.read().decode('utf-8')

            # Attempt to parse as JSON if the API returns a JSON object
            try:
                json_data = json.loads(data)
                # Common keys for IP APIs: 'ip', 'query', 'public_ip'
                for key in ['ip', 'query', 'public_ip']:
                    if key in json_data:
                        return str(json_data[key])
            except json.JSONDecodeError:
                pass

            # Fallback: Use regex to find an IP address in the raw response text
            match = re.search(IP_REGEX, data)
            if match:
                return match.group(0)

            raise Exception("Could not extract IP address from API response.")

    except Exception as e:
        raise Exception(f"Failed to retrieve public IP: {str(e)}")

