import json
import os
def task_func(directory, string):
    """
    Recursively scans the specified directory for JSON files and checks if the 
    given string exists as a value or key within the JSON data structure.
    """
    matches = []

    # Walk through the directory and subdirectories
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        data = json.load(f)

                    # Helper function to recursively search the JSON structure
                    def contains_string(obj, target):
                        if isinstance(obj, str):
                            return obj == target
                        elif isinstance(obj, dict):
                            # Check keys and values
                            for k, v in obj.items():
                                if k == target or contains_string(v, target):
                                    return True
                        elif isinstance(obj, list):
                            # Check elements in list
                            for item in obj:
                                if contains_string(item, target):
                                    return True
                        return False

                    if contains_string(data, string):
                        matches.append(file_path)
                except (json.JSONDecodeError, IOError, PermissionError):
                    # Skip files that are not valid JSON or cannot be read
                    continue

    return matches

