import json
import re
import pandas as pd
def task_func(json_str):
    """
    Processes a JSON string by converting it into a dictionary, normalizing 
    the numerical values by doubling them, and constructing a Pandas DataFrame.
    """
    if not json_str:
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    normalized_data = {}

    for key, value in data.items():
        # Handle lists of values
        if isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    new_list.append(float(item * 2))
                elif isinstance(item, str):
                    # Extract numbers from strings using regex
                    match = re.search(r"[-+]?\d*\.\d+|\d+", item)
                    if match:
                        new_list.append(float(match.group()) * 2)
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            normalized_data[key] = new_list

        # Handle single numerical values
        elif isinstance(value, (int, float)):
            normalized_data[key] = float(value * 2)

        # Handle strings that might contain numbers
        elif isinstance(value, str):
            match = re.search(r"[-+]?\d*\.\d+|\d+", value)
            if match:
                normalized_data[key] = float(match.group()) * 2
            else:
                normalized_data[key] = value

        # Keep other types as-is
        else:
            normalized_data[key] = value

    try:
        # Create DataFrame. If values are lists of different lengths, 
        # orient='index' or a list of dicts is safer.
        # Given the requirement for a flat dictionary, we wrap in a list.
        df = pd.DataFrame([normalized_data])
        return df
    except Exception:
        return pd.DataFrame()

